body:
Jira Link: [DB-19204](https://yugabyte.atlassian.net/browse/DB-19204)
### Description

Scenario :

```
CREATE TABLE _16_s_1_base (id INT PRIMARY KEY, val TEXT);
INSERT INTO _16_s_1_base SELECT i, 'val' || i FROM generate_series(1, 1000) i;

BEGIN ISOLATION LEVEL REPEATABLE READ;

SAVEPOINT s1_start;
CREATE MATERIALIZED VIEW _16_s_1_mv AS SELECT * FROM _16_s_1_base;
SELECT COUNT(*) FROM _16_s_1_mv;

SAVEPOINT s2_created_mv;
INSERT INTO _16_s_1_base SELECT i, 'val' || i FROM generate_series(1001, 2000) i;
REFRESH MATERIALIZED VIEW _16_s_1_mv;
SELECT COUNT(*) FROM _16_s_1_mv;

SAVEPOINT s3_refreshed_mv;
CREATE INDEX _16_idx_mv ON _16_s_1_mv (val);
SELECT indexname FROM pg_indexes WHERE indexname = '_16_idx_mv';

ROLLBACK TO SAVEPOINT s3_refreshed_mv;

ROLLBACK;
```

Either Rollback to save point / Rollback fails with ;

```
yugabyte=*# ROLLBACK TO SAVEPOINT s3_refreshed_mv;
FATAL:  Failed to rollback to subtransaction 4: Rolling back to sub-transaction when another sub-transaction rollback in progress. transaction: af082d76-43f0-446a-aa46-986ec6e58c65, sub_transaction_id: 4, sub_transaction_id_in_progress: 0
WARNING:  AbortSubTransaction while in ABORT state
FATAL:  Failed to rollback to subtransaction 4: Rolling back to sub-transaction when another sub-transaction rollback in progress. transaction: af082d76-43f0-446a-aa46-986ec6e58c65, sub_transaction_id: 4, sub_transaction_id_in_progress: 0
SSL connection has been closed unexpectedly
The connection to the server was lost. Attempting reset: Succeeded.
SSL connection (protocol: TLSv1.3, cipher: TLS_AES_256_GCM_SHA384, compression: off)
```

2:

```
CREATE TABLE _8_s_1 (
    id INT,
    p_date DATE NOT NULL,
    val TEXT,
    email TEXT,
    PRIMARY KEY(id, p_date)
) PARTITION BY RANGE (p_date);

CREATE TABLE _8_s_1_p1 PARTITION OF _8_s_1
FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');

BEGIN ISOLATION LEVEL REPEATABLE READ ;
SAVEPOINT s1_setup;

CREATE INDEX _8_idx_email ON _8_s_1 (email);

ALTER TABLE _8_s_1 ADD COLUMN temp_col TEXT;

SELECT COUNT(*) FROM pg_indexes WHERE indexname = '_8_idx_email';

SAVEPOINT s2_renames;

ALTER TABLE _8_s_1 RENAME COLUMN val TO notes;

ALTER TABLE _8_s_1 RENAME COLUMN email TO user_email;

CREATE INDEX _8_idx_notes ON _8_s_1 (notes);
ALTER TABLE _8_s_1 RENAME TO _8_s_1_renamed;

SELECT table_name FROM information_schema.tables
WHERE table_name = '_8_s_1_renamed';

SELECT column_name FROM information_schema.columns
WHERE table_name = '_8_s_1_renamed' AND column_name = 'user_email';

SAVEPOINT s3_final_adds;

ALTER TABLE _8_s_1_renamed ADD COLUMN status BOOLEAN;

ALTER TABLE _8_s_1_renamed ADD COLUMN flags INT;

CREATE INDEX _8_idx_status ON _8_s_1_renamed (status);

ALTER TABLE _8_s_1_p1 RENAME TO _8_s_1_p1_renamed;
SELECT table_name FROM information_schema.tables
WHERE table_name = '_8_s_1_p1_renamed';

ROLLBACK TO SAVEPOINT s2_renames;
```

